SELECT a.*, p.real_name AS patient_name, p.phone AS patient_phone, dp.name AS department_name FROM appointment a JOIN patient p ON p.id = a.patient_id JOIN department dp ON dp.id = a.department_id WHERE a.doctor_id = #{doctorId}
AND a.status = #{status}
ORDER BY a.appointment_date, a.queue_no, a.id LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
  FROM appointment
 WHERE doctor_id = #{doctorId}

   AND status = #{status}

SELECT *
  FROM appointment
 WHERE id = #{appointmentId}
   AND doctor_id = #{doctorId}
   FOR UPDATE

